function methodPanel(){return `<section class="panel"><h3>Кейіпкердің шешім зертханасы</h3><p>Бұл платформаға ұсынылған әдістемелік модель. Дайын психологиялық тест емес. Кейіпкер туралы пайым әрдайым мәтінмен тексеріледі.</p><ol><li><strong>Әрекет:</strong> кейіпкер не істеді? Мәтіндегі орнын белгілеңіз.</li><li><strong>Уәж:</strong> не себеп болуы мүмкін? Айтылмаған уәжді болжам деп белгілеңіз.</li><li><strong>Ықпал:</strong> бала не сезінді, нені үйренді? Мәтіннен белгі табыңыз.</li><li><strong>Балама:</strong> басқа түсіндіруді ұсыныңыз және екінші эпизодпен тексеріңіз.</li><li><strong>Перспектива:</strong> бала мен ересек баяндаушының бағасын салыстырыңыз.</li></ol><p><strong>Әже:</strong> ертегі айту мен түнгі оқиғадан кейін есікті бекітуді салыстыру. <strong>Әке:</strong> сәлемді сыбырлап еске салу мен тәттіні тең бөлуді салыстыру.</p><p><strong>Нәтиже:</strong> екі эпизодқа сүйенген 80–100 сөздік көпқырлы мінездеме. Дескриптор: әрекет дәл, уәж бен дерек ажыратылған, ықпал түсіндірілген, балама тексерілген.</p></section>`;}
function taskHTML(a,j){return `<section class="panel task"><div class="tag">${j+1}-ТАПСЫРМА · ${durations[j]} МИНУТ · ${esc(a[1])}</div><h3>${esc(a[0])}</h3><p><strong>Мақсаты:</strong> ${esc(a[2])}</p><p><strong>Орындалуы:</strong> ${esc(a[3])}</p><div class="desc"><strong>Бағалау дескрипторлары</strong>${list(a[4])}</div><p><strong>Қолдау:</strong> ${esc(a[5])}</p><p><strong>Тереңдету:</strong> ${esc(a[6])}</p><details><summary>Мұғалімге талқылау бағдары</summary><p>${esc(a[7])}</p><p>Дәлел орынды болса, өзге негізделген түсіндіруді де қабылдаңыз. Әр дескрипторға «орындады / нақтылау қажет» деп кері байланыс беріңіз.</p></details></section>`;}
render=function(){const l=lessons[current],u=units[current];let body='';
if(tab==='plan')body=`<div class="toolbar"><button class="primary" onclick="exportLesson('plan')">Жоспарды жүктеу (HTML)</button><button class="ghost" onclick="printLesson('plan')">Жоспарды басып шығару / PDF</button></div><div class="two"><div><section class="panel"><h3>60 минуттағы оқу нәтижесі</h3><p>${esc(l.goal)}</p><p><strong>Зерттеу сұрағы:</strong> ${esc(u.question)}</p><p><strong>Мәтіндік тірек:</strong> ${esc(u.anchor)}</p><a href="${readingURL}" target="_blank" rel="noopener noreferrer">1–2 бөлімді ашу ↗</a></section><section class="panel"><h3>Сабақ барысы · 60 минут</h3><div class="timeline">${l.plan.map((p,j)=>`<div class="step"><strong>${esc(p[0])}<small>${j*4+1}–${j*4+4} слайд</small></strong><span>${esc(p[1])}</span></div>`).join('')}</div></section></div><div><section class="panel"><h3>Мұғалімнің дайындығы</h3><p>${esc(u.prep)}</p><p>Мәтін, дәптер немесе А3 парағы, маркер және экран жеткілікті. Бейне қолданылса, ол 6–16 минут аралығындағы мәтінмен жұмыс кезеңінің 2–3 минутын алмастырады. Ойнатылмаса, сол үзіндіні мұғалім оқиды.</p></section><section class="panel"><h3>Концептілер және саралау</h3><p>${esc(concepts[current])}</p><p><strong>Ортақ өзек:</strong> перспектива, мінез, көзқарас. Ғаламдық мәнмәтін: уақыт пен кеңістіктегі бағдар.</p><p><strong>Зерттеу идеясы:</strong> кейіпкерлердің рухани дамуына ұлттық тәрбиені дамыту перспективалары әсер етеді.</p><p>Қолдау қажет оқушы қысқа белгіленген үзіндімен, сөздікпен және сөйлем тірегімен жұмыс істейді. Дайын оқушы балама түсіндіруді тексереді. Барлығы ортақ мақсатқа жетеді. Әр тапсырманың нақты қолдауы «Тапсырмалар» бөлімінде.</p></section><section class="panel"><h3>Қалыптастырушы бағалау</h3><p>А: дәлел мен талдаудың байланысы. Д: ойдың жүйелілігі, әдеби термин, сөз қолданысы және сауаттылық.</p><p>Мұғалім мәтінмен жұмыс кезінде екі оқушыны тыңдайды, талдау кезінде бір топтың дәлелін тексереді, соңында шығу билетін жинайды. Тапсырма дескрипторлары MYP 0–8 бағасына автоматты аударылмайды.</p></section></div></div>${current===2||current===3?methodPanel():''}`;
if(tab==='tasks')body=u.activities.map(taskHTML).join('');
if(tab==='slides'){const s=l.slides[slide],a=u.activities[Math.floor(slide/4)];body=`<div class="toolbar"><label for="slideSelect">Слайд</label><select id="slideSelect" onchange="slide=Number(this.value);render()">${l.slides.map((x,j)=>`<option value="${j}" ${j===slide?'selected':''}>${j+1}. ${esc(x[0])}</option>`).join('')}</select><button class="ghost" onclick="togglePresentation()">Толық экран</button><button class="ghost" onclick="exportLesson('slides')">Презентацияны жүктеу (HTML)</button><button class="ghost" onclick="printLesson('slides')">Слайдтарды басып шығару / PDF</button></div><div id="presentation" class="presentation"><div class="slide"><div class="eyebrow">${current+1}-САБАҚ · ${slide+1} / 24 · ${esc(s[2])}</div><h2>${esc(s[0])}</h2><p>${esc(s[1]).replaceAll('\n','<br>')}</p></div><div class="slidebar"><button onclick="changeSlide(-1)" ${slide===0?'disabled':''}>← Алдыңғы</button><span>${slide+1} / 24</span><button onclick="changeSlide(1)" ${slide===23?'disabled':''}>Келесі →</button></div></div><p class="note">← → пернелерімен ауыстырыңыз. Әр төрт слайд бір оқу кезеңін сүйемелдейді, уақыт төрт слайдқа ортақ.</p><details ${showNotes?'open':''} ontoggle="showNotes=this.open"><summary>Мұғалім жазбалары және саралау</summary><p><strong>Кезең мақсаты:</strong> ${esc(a[2])}</p><p><strong>Қолдау:</strong> ${esc(a[5])}</p><p><strong>Тереңдету:</strong> ${esc(a[6])}</p><p><strong>Тірек:</strong> ${esc(u.anchor)} <a href="${readingURL}" target="_blank" rel="noopener noreferrer">Мәтін</a></p></details>`;}
if(tab==='resources')body=`<section class="panel"><h3>Осы сабақтағы медиатапсырма</h3><p>${esc(mediaPrompts[current])}</p><p><strong>Мақсаты:</strong> тыңдалымдағы ойды түпнұсқа мәтінмен салыстыру.</p><p><strong>Дескрипторлар:</strong> бір тұжырымды тіркейді, мәтіндегі орнын тексереді, сәйкестік не айырманы түсіндіреді.</p><p><strong>Уақыты:</strong> 2–3 минут тыңдау, 2 минут салыстыру, мәтінмен жұмыс кезеңінің ішінде. Мұғалім сабағына дейін тиісті эпизодты табады. Нақты таймкод расталмаған. Бейне міндетті емес: мәтінді дауыстап оқуға болады.</p></section><div class="two"><section class="panel"><h3>YouTube және басқа дереккөздер</h3>${library.map(v=>`<a class="resource" href="${v.url}" target="_blank" rel="noopener noreferrer">${esc(v.title)} ↗<small>${esc(v.kind)} · ${esc(v.use)}</small></a>`).join('')}<p class="note">Сілтемелердің атауы мен ресми дереккөз сәйкестігі 16.09.2026 күні тексерілді. Бейнені толық ойнату және нақты үзінді уақыттары расталмаған.</p></section><section class="panel"><h3>Негізгі оқу материалы</h3><p>${esc(u.anchor)}</p><a class="resource" href="${readingURL}" target="_blank" rel="noopener noreferrer">Оқушы мәтіні · 1–2 бөлім ↗</a><a class="resource" href="https://platform-new-ecru.vercel.app/${studentRoutes[current]}" target="_blank" rel="noopener noreferrer">Сәйкес оқушы тапсырмалары ↗</a><p>Оқушы платформасының жүктелген мәтіні мен әдебиет теориясы негізге алынды. Бөлім атаулары осы оқу үзіндісіне қатысты. Толық кітаптағы тараулар мен аудиокітап нөмірлері өзгеше болуы мүмкін.</p><h3>Тыңдалымға саралау</h3><p>Қолдау: тыңдар алдында қысқа үзіндіні оқып, тірек сөздерді белгілеу. Тереңдету: диктордың интонациясы өз түсіндіруіңізге қалай ықпал еткенін бағалау.</p></section></div>`;
if(tab==='game')body=`<section class="panel"><h3>${esc(u.activities[current===8?0:3][0])} · сынып ойыны</h3><p><strong>Мақсаты:</strong> ${esc(u.activities[current===8?0:3][2])}</p><p>${esc(u.activities[current===8?0:3][3])}</p><div class="desc"><strong>Дескрипторлар</strong>${list(u.activities[current===8?0:3][4])}</div><p>Топта оқырман, дәлел іздеуші, баяндамашы және бақылаушы рөлдерін ауыстырып отырыңыз. Дұрыс тұжырымға 1, орынды мәтіндік дәлелге 1 ұпай беріледі. Әр топтың екінші мүмкіндігі бар. Бұл ойын сабақ жоспарындағы тиісті әрекеттің ішінде орындалады.</p></section><section class="panel"><h3>Жылдам тексеру · ${current===8?'5':'3'} сұрақ</h3><p>Ойын соңында қате жауап түсіндірмесімен жұмыс істеңіз. Ұпай қалыптастырушы белгі ғана.</p><div id="lessonGame"></div></section>`;
if(tab==='method')body=methodPanel();
layout(`<div class="detailhead"><div><span class="eyebrow">${esc(l.part)} · ${current+1}-САБАҚ · 60 МИНУТ</span><h1>${esc(l.title)}</h1><p>${esc(u.question)}</p></div><button class="ghost" onclick="home()">← Сабақтар картасы</button></div><div class="tabs">${[['plan','60 минуттық жоспар'],['slides','Презентация · 24'],['tasks','Тапсырмалар · 6'],['resources','Медиа және дереккөздер'],['game','Ойындар'],['method','Кейіпкер зертханасы']].map(([v,t])=>`<button class="tab ${tab===v?'active':''}" onclick="setTab('${v}')">${t}</button>`).join('')}</div>${body}`);
app.querySelector('.pill').textContent='9 × 60 минут · 540 минут';if(tab==='game')drawGame();
};
const oldChange=changeSlide;
changeSlide=function(d){const full=!!document.fullscreenElement;slide=Math.max(0,Math.min(23,slide+d));if(full){const s=lessons[current].slides[slide];document.querySelector('.slide').innerHTML=`<div class="eyebrow">${current+1}-САБАҚ · ${slide+1} / 24 · ${esc(s[2])}</div><h2>${esc(s[0])}</h2><p>${esc(s[1]).replaceAll('\n','<br>')}</p>`;document.querySelector('.slidebar').innerHTML=`<button onclick="changeSlide(-1)" ${slide===0?'disabled':''}>← Алдыңғы</button><span>${slide+1} / 24</span><button onclick="changeSlide(1)" ${slide===23?'disabled':''}>Келесі →</button>`;}else render();};
function togglePresentation(){const el=document.getElementById('presentation');if(document.fullscreenElement)document.exitFullscreen();else if(el.requestFullscreen)el.requestFullscreen().catch(()=>alert('Толық экран қолжетімсіз. Презентацияны жүктеп, бөлек ашыңыз.'));}
document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&tab==='slides'&&current>=0)render()});
document.addEventListener('keydown',e=>{if(tab==='slides'&&current>=0&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)){if(e.key==='ArrowRight'){e.preventDefault();changeSlide(1)}if(e.key==='ArrowLeft'){e.preventDefault();changeSlide(-1)}}});
function activeQuestions(){return current===8?[...gameBank[8],gameBank[2][1],gameBank[7][2]]:gameBank[current];}
function drawGame(){const pool=activeQuestions(),box=document.getElementById('lessonGame');if(gameIndex===pool.length){box.innerHTML=`<h3>Нәтиже: ${gameScore}/${pool.length}</h3><p>Бір қате не күмәнді жауапты мәтіннен тексеріп, дұрыс түсіндіру жазыңыз.</p><button class="primary" onclick="gameIndex=0;gameScore=0;gamePicked=null;drawGame()">Қайта ойнау</button>`;return;}const x=pool[gameIndex];box.innerHTML=`<p>${gameIndex+1} / ${pool.length}</p><h3>${esc(x[0])}</h3><div class="choices">${x[1].map((t,j)=>`<button class="choice ${gamePicked!==null?(j===x[2]?'correct':j===gamePicked?'wrong':''):''}" onclick="answerGame(${j})" ${gamePicked!==null?'disabled':''}>${esc(t)}</button>`).join('')}</div>${gamePicked!==null?`<div role="status"><p><strong>${gamePicked===x[2]?'Дұрыс.':'Дұрыс жауап: '+esc(x[1][x[2]])+'.'}</strong> ${esc(x[3])}</p></div><button class="primary" onclick="gameIndex++;gamePicked=null;drawGame()">${gameIndex===pool.length-1?'Нәтиже':'Келесі →'}</button>`:''}`;}
function answerGame(j){if(gamePicked!==null)return;gamePicked=j;if(j===activeQuestions()[gameIndex][2])gameScore++;drawGame();}
function exportHTML(kind){const l=lessons[current],u=units[current];let content=kind==='slides'?l.slides.map((s,i)=>`<section class="page"><small>${current+1}-сабақ · ${i+1}/24 · ${esc(s[2])}</small><h1>${esc(s[0])}</h1><p>${esc(s[1]).replaceAll('\n','<br>')}</p></section>`).join(''):`<h1>${current+1}. ${esc(l.title)}</h1><p>60 минут · ${esc(l.part)}</p><h2>Сабақ мақсаты</h2><p>${esc(l.goal)}</p><p>${esc(u.question)}</p><p><strong>Концепт:</strong> ${esc(concepts[current])}</p><p><strong>Дайындық:</strong> ${esc(u.prep)}</p><p><strong>Мәтін:</strong> ${esc(u.anchor)}</p><h2>Минуттық жоспар</h2>${l.plan.map(x=>`<p><strong>${esc(x[0])}</strong> ${esc(x[1])}</p>`).join('')}<h2>Тапсырмалар және бағалау</h2>${u.activities.map(taskHTML).join('')}<h2>Медиа</h2><p>${esc(mediaPrompts[current])}</p><p>Бейне мәтінмен жұмыс кезеңінің 2–3 минутын алмастырады. Сәйкес үзіндіні алдын ала таңдаңыз.</p><p>Мақсат: тыңдалым мен мәтінді салыстыру. Дескрипторлар: тұжырымды тіркейді, мәтіннен тексереді, сәйкестік не айырманы түсіндіреді.</p>${library.map(v=>`<p><a href="${v.url}">${esc(v.title)}</a>: ${esc(v.use)}</p>`).join('')}`;
return `<!doctype html><html lang="kk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(l.title)}</title><style>body{font:18px/1.6 Arial,sans-serif;color:#203c30;margin:32px auto;max-width:1100px;padding:0 24px}h1{font-size:36px;line-height:1.2}h2{font-size:26px}.page{min-height:85vh;padding:5vh 4vw;border-bottom:2px solid #315b48;display:flex;flex-direction:column;justify-content:center}.page p{font-size:clamp(22px,3vw,36px);line-height:1.5;max-width:1000px}.page h1{font-size:clamp(32px,4vw,52px)}small{font-size:16px}.panel{margin:32px 0}a{color:#315b48}@media print{@page{size:${kind==='slides'?'A4 landscape':'A4'};margin:15mm}.page{break-after:page;min-height:0;height:170mm;padding:0;border:0;overflow:hidden}.page h1{font-size:30pt}.page p{font-size:20pt}.page:last-child{break-after:auto}body{margin:0;padding:0;font-size:11pt}.panel{break-inside:avoid}button{display:none}}</style><body>${content}<footer style="display:${kind==='slides'?'none':'block'}"><p>«Ұядан ұшқан құндылық» · Б. Момышұлы «Ұшқан ұя», 1–2 бөлім. Негізгі мәтін: <a href="${readingURL}">оқушы платформасы</a>. Дескрипторлар қалыптастырушы бағалауға арналған.</p></footer></body></html>`;}
function exportLesson(kind){const b=new Blob([exportHTML(kind)],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`ushqan-uya-${current+1}-${kind}.html`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function printLesson(kind){let f=document.getElementById('printFrame');if(f)f.remove();f=document.createElement('iframe');f.id='printFrame';f.title='Басып шығару';f.style.cssText='position:fixed;width:1px;height:1px;left:-9999px';f.srcdoc=exportHTML(kind);f.onload=()=>{f.contentWindow.focus();f.contentWindow.print()};document.body.appendChild(f);}
home();

